glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec2 a_uv0;
in vec4 a_color;
out vec2 v_uv0;
out vec4 v_color;
void main () {
  vec4 pos = cc_matViewProj * cc_matWorld * vec4(a_position, 1.0);
  gl_Position = pos;
  v_uv0 = a_uv0;
  v_color = a_color;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec2 v_uv0;
in vec4 v_color;
uniform sampler2D texture;
uniform Constant {
  vec4 colorTop;
  vec4 colorBottom;
};
void main () {
  vec4 texColor = texture2D(texture, v_uv0);
  float gradientFactor = 1.0 - v_uv0.y;
  vec4 gradientColor = mix(colorTop, colorBottom, gradientFactor);
  vec3 rgb = gradientColor.rgb * texColor.a * v_color.rgb;
  float alpha = texColor.a * v_color.a;
  vec4 finalColor = vec4(rgb, alpha);
  if (finalColor.a < 0.5) {
    discard;
  }
  gl_FragColor = finalColor;
}

glsl1.vert:
precision highp float;
uniform mat4 cc_matViewProj;
uniform mat4 cc_matWorld;
attribute vec3 a_position;
attribute vec2 a_uv0;
attribute vec4 a_color;
varying vec2 v_uv0;
varying vec4 v_color;
void main () {
  vec4 pos = cc_matViewProj * cc_matWorld * vec4(a_position, 1.0);
  gl_Position = pos;
