glsl1.frag:
precision highp float;
#if USE_ALPHA_TEST
#endif
varying vec2 v_uv0;
varying vec4 v_color;
uniform sampler2D texture;
uniform vec4 colorTop;
uniform vec4 colorBottom;
void main () {
  vec4 texColor = texture2D(texture, v_uv0);
